source('experiments/swing_xgboost_v1/functions.R')
read<-function(n)fread(file.path(SR,n))
m<-read('component_metrics.csv');boot<-read('component_bootstrap.csv');im<-read('integrated_metrics.csv');ib<-read('integrated_bootstrap.csv');support<-read('support.csv');tails<-read('tails.csv');sens<-read('sensitivity.csv')
checks<-read('verification.csv');unit<-read('unit_verification.csv');predchecks<-read('prediction_verification.csv');stopifnot(all(checks$passed),all(unit$passed),all(predchecks$passed))
sel<-rbindlist(lapply(SSTAGES,function(st)read(paste0('selection_',st,'.csv'))))
table<-function(d,cols){z<-as.data.frame(lapply(d[,..cols],function(x)if(is.numeric(x))format(x,digits=7,trim=TRUE,scientific=FALSE)else as.character(x)));c(paste0('| ',paste(cols,collapse=' | '),' |'),paste0('| ',paste(rep('---',length(cols)),collapse=' | '),' |'),apply(z,1,function(x)paste0('| ',paste(x,collapse=' | '),' |')))}
primary<-ib[year==2025&population=='common_supported'&reference=='gam'&metric=='rmse']
vscontact<-ib[year==2025&population=='common_supported'&reference=='contact_only'&metric=='rmse']
verdict<-function(row)if(row$ci_high<0)'improves'else if(row$ci_low>0)'worsens'else 'does not clearly change'
h25<-read('hitters_2025.csv')[qualified==TRUE]
lines<-c('# Complete XGBoost swing-path comparison','',
 sprintf('On common-supported factual 2025 swings, the full XGBoost path %s RMSE versus the population GAM path: difference %.6f runs [%.6f, %.6f]. Relative to changing contact alone, it %s RMSE: difference %.6f [%.6f, %.6f].',verdict(primary),primary$difference,primary$ci_low,primary$ci_high,verdict(vscontact),vscontact$difference,vscontact$ci_low,vscontact$ci_high),'',
'2025 is exploratory. Contact XGBoost was already selected and evaluated in an earlier experiment. The three new stage specifications and all-path comparison were fixed before their new 2025 predictions. There was no 2024/2025 tuning or recalibration and no activation.','','Component evidence is mixed: contact and BIP probability improve in both evaluated seasons, while caught-tip log loss is worse in both. BIP-value MAE is worse in both seasons; its 2025 RMSE difference does not clearly distinguish the models. These results do not support replacing every swing GAM with this XGBoost specification.','',
'Compared with contact-only XGBoost, the full path has no clear additional supported-swing RMSE gain in 2025 and worsens it slightly in 2024. Component classification improvements therefore should not be read as a demonstrated improvement in every stage or in counterfactual decision evaluation.','',
'## Model contract and overfitting controls','',
'The path contains P(contact|swing), P(BIP|contact), P(caught tip|non-BIP contact) and expected BIP runs+RE_after. Contact reuses its frozen depth-5/803-round XGBoost. Each remaining model uses exactly its updated-history population GAM predictors, final training transformations, eligible 2022–23 training rows and verified labels. Hitter/pitcher contact and power profiles are strictly prior-season. Same-pitch exit velocity, launch angle, result and actor identities are excluded as predictors. The suffix _ev_2021 is retained for compatibility but receives the appropriate previous-season power profile.','',
'Three fixed depths (3/4/5), learning rate .05, min_child_weight 50, L2=10, L1=1, subsample .8, colsample_bytree .9, CPU histogram/two threads, maximum 1200 rounds and 60-round early stopping. Development preprocessing and training use 2022 only, with 2023 validation. BIP-value development labels use 2022-only RE288. Final models refit on 2022–23; final/evaluation BIP targets use the same frozen 2022–23 RE288 as the GAM. Value XGBoost uses the positive Poisson-mean objective and RMSE selection on nonnegative continuous targets; it does not assert a literal count distribution. Regularization and temporal testing reduce overfitting risk but cannot prove its absence.','',
table(sel,c('stage','depth','best_rounds','trained_rounds','cap_reached','validation_loss')),'',
'## Factual component comparisons','',
'Probability stages: log loss, Brier and calibration. Value stage: RMSE, MAE and bias in runs+RE_after. Value is not a probability. All comparisons use identical stage-specific evaluation cohorts.','',
table(m[year==2025&stage!='value'],c('stage','arm','n','log_loss','brier','bias','calibration_intercept','calibration_slope')),'',
table(m[year==2025&stage=='value'],c('stage','arm','n','rmse','mae','bias')),'',
table(boot[year==2025],c('stage','metric','difference','ci_low','ci_high')),'',
'Differences are XGBoost minus GAM. Negative loss/error differences favor XGBoost; signed bias changes have no universally favorable direction. Every calibration bin and all count/family/region/prior-profile/history-exposure slices are saved in calibration.csv and slices.csv. Slice results are descriptive and unadjusted for multiplicity. 2024 tables are saved as secondary replication.','',
'## Integrated factual swing values','',
'gam = all population GAM stages; contact_only = XGBoost contact with GAM post-contact stages; xgboost = all four XGBoost stages. All arms share take values, league policy, RE288 transitions and frozen 2024 reference. Each outcome branch is a probability, and the four sum to one. Swing Q is their weighted average of branch-specific runs+RE values.','',
'Factual targets use the realized whiff/foul/caught-tip branch transition or verified BIP runs+RE_after. Unverified BIP targets are omitted identically from all factual metrics. Branch log loss in the integrated table uses that same verified-target cohort. No factual target exists for hypothetical swings on takes.','',
table(im[year==2025],c('population','arm','n','rmse','mae','bias','branch_log_loss')),'',
table(ib[year==2025],c('population','reference','metric','difference','ci_low','ci_high')),'',
'all_factual_swings includes unsupported extrapolations for audit. gam_supported retains the earlier population-GAM safeguards and discloses candidate failures before adding common restrictions; it is diagnostic. common_supported is the primary score and factual-value cohort.','',
'## Support, scores and boundary diagnostics','',table(support,names(support)),'',
'Common support retains original exclusions (including the 34 RE ordering-warning states), checks numeric training ranges under updated histories, and requires both BIP value models within the original training-target range. No unsupported pitch is promoted. Qualification remains 500 supported pitches, 60 supported games and 70% coverage; Decision+ uses the fixed 2024 center and scale. Point estimates are descriptive season averages.','',
table(tails[year==2025],c('action','primary_supported','gam_supported','n','mean_delta_q','p99_abs_delta_q','max_abs_delta_q','change_runs100')),'','The largest unsupported 2025 take difference is 98.414 runs: the population GAM extrapolates Q(swing) to 99.284, versus 0.869 from XGBoost, on pitch 776724/21/5. This pitch was already unsupported and fails updated range checks. Its GAM BIP value is 100.366, versus 0.937 from XGBoost. This illustrates extreme GAM extrapolation outside support; the bounded-looking tree estimate is not evidence that the hypothetical action value is valid. No such row enters hitter scores.','',
table(sens[year==2025],names(sens)),'',
'Sensitivity follows baseline-qualified hitters retaining at least 500 pitches and 60 games under the stricter restriction; those diagnostic rows do not necessarily retain 70% coverage. It measures changes in the XGBoost-minus-GAM effect, not a new qualification or support policy.','',
'Largest absolute 2025 qualified hitter changes on the common cohort:','',
table(read('largest_movements_2025.csv'),c('batter_name','supported','coverage','gam_decision_plus','contact_only_decision_plus','xgboost_decision_plus','delta_plus','delta_vs_contact','vs_gam_low','vs_gam_high')),'',sprintf('Among qualified hitters, median absolute full-path change versus GAM is %.3f Decision+ points and maximum %.3f. Versus contact-only, the corresponding changes are %.3f and %.3f.',median(abs(h25$delta_plus)),max(abs(h25$delta_plus)),median(abs(h25$delta_vs_contact)),max(abs(h25$delta_vs_contact))),'',
'vs_gam_low/high are fresh conditional game-sampling intervals for runs/100 differences, not Decision+ intervals or estimates of uncertainty in latent talent. Complete hitter tables and game totals are saved separately. These comparisons isolate updated-history model-family changes; they do not measure the complete difference from active v6 with its original histories.','',
'## Verification, limits and reproduction','',sprintf('%d independent artifact checks, %d unit checks and %d public prediction checks passed.',nrow(checks),nrow(unit),nrow(predchecks)),
'Checks reconstruct training preprocessing/labels/features, the 2022-only development RE table, selection, factual cohorts/predictions/calibration/slices/bootstrap, branches and score arithmetic, support, qualification, reference scaling and fresh hitter intervals. Tests include singleton/batch/order/native serialization, corrupted outcomes, unseen histories and invalid core inputs. Original upstream artifacts retain their input hashes.','',
'Intervals condition on all fitted models and RE/reference quantities. They omit full training refits, hyperparameter/model selection, RE/reference uncertainty and unmeasured action selection. Accurate observed-swing predictions do not validate hypothetical swings on takes or identify causal decision talent. No old model uncertainty intervals or preference labels were reused.','',
'From the project root:','', '```sh','Rscript experiments/swing_xgboost_v1/tests.R','Rscript experiments/swing_xgboost_v1/train.R','Rscript experiments/swing_xgboost_v1/evaluate.R','Rscript experiments/swing_xgboost_v1/verify.R','Rscript experiments/swing_xgboost_v1/verify_prediction.R','Rscript experiments/swing_xgboost_v1/report.R','```','',
'Training refuses to overwrite an aggregate frozen experiment. Before that freeze, stage bundles may be reused only with matching training-code/protocol hashes. Required original data and fitted GAM/contact-XGBoost artifacts are recorded in input_hashes.csv. Package versions are in sessionInfo.txt. predict.R exposes raw swing model estimates; callers must still apply the support contract.','',
'[XGBoost objective/regularization documentation](https://xgboost.readthedocs.io/en/stable/parameter.html)','',
'![Swing-path comparisons](comparison.png)')
writeLines(lines,file.path(SR,'REPORT.md'))
png(file.path(SR,'comparison.png'),width=1800,height=1400,res=180);par(mfrow=c(2,2),mar=c(4.5,4.5,3,1),las=1)
cols<-c(gam='#777777',contact_only='#2466aa',xgboost='#c24e22')
for(st in c('bip','tip')){
 zz<-read('calibration.csv')[year==2025&stage==st]
 plot(NA,xlim=c(0,if(st=='tip').2 else 1),ylim=c(0,if(st=='tip').2 else 1),xlab='Mean predicted probability',ylab='Observed frequency',main=paste('2025',st,'calibration'));abline(0,1,lty=2,col='#bbbbbb')
 for(a in c('gam','xgboost')){z<-zz[arm==a&n>=100];setorder(z,predicted);lines(z$predicted,z$observed,col=cols[a],type='b',pch=16,cex=.6)}
 legend('topleft',c('gam','xgboost'),col=cols[c('gam','xgboost')],lty=1,bty='n',cex=.8)
}
z<-im[year==2025&population=='common_supported'];barplot(z$rmse,names.arg=z$arm,col=cols[z$arm],ylab='Factual swing Q RMSE (runs)',main='2025 common-supported swings',ylim=c(0,max(z$rmse)*1.15))
hit<-read('hitters_2025.csv')[qualified==TRUE];plot(hit$gam_decision_plus,hit$xgboost_decision_plus,pch=16,cex=.6,col='#2466aa77',xlab='Population GAM Decision+',ylab='Full XGBoost Decision+',main='Same supported pitches and reference');abline(0,1,lty=2,col='#bbbbbb')
dev.off();fwrite(x_hash(list.files(SROOT,pattern='\\.(R|md)$',full.names=TRUE)),file.path(SR,'final_code_hashes.csv'));cat(lines[3],'\n')
